from collections import Counter
from itertools import combinations
from typing import FrozenSet, List, Tuple

Basis = FrozenSet[int]


def census(config: List[Basis]) -> Counter:
    """Total multiset union: how many bases each element lies in."""
    c: Counter = Counter()
    for b in config:
        c.update(b)
    return c


def is_quadratic_move(b1: Basis, b2: Basis, c1: Basis, c2: Basis) -> bool:
    """A move {b1,b2} -> {c1,c2} is legal iff the pooled elements match."""
    return Counter(b1) + Counter(b2) == Counter(c1) + Counter(c2)


def all_repartitions(b1: Basis, b2: Basis, r: int, n: int) -> List[Tuple[Basis, Basis]]:
    """Every way to repartition the pool of b1,b2 into two r-subsets (bases of U_{r,n})."""
    pool = Counter(b1) + Counter(b2)
    out = []
    for c1 in (frozenset(s) for s in combinations(range(n), r)):
        rem = pool - Counter(c1)
        c2 = frozenset(rem.keys())
        if Counter(c2) == rem and len(c2) == r and is_quadratic_move(b1, b2, c1, c2):
            out.append((c1, c2))
    return out


if __name__ == "__main__":
    b1, b2 = frozenset({0, 1}), frozenset({2, 3})
    print("census before:", dict(census([b1, b2])))
    for c1, c2 in all_repartitions(b1, b2, 2, 4):
        assert census([b1, b2]) == census([c1, c2])
        print(f"  legal move -> {sorted(c1)}, {sorted(c2)}  (census preserved)")

