from collections import Counter
from itertools import combinations
from typing import FrozenSet, List, Set, Tuple

Basis = FrozenSet[int]
Key = Tuple[Tuple[int, ...], ...]


def census(cfg: List[Basis]) -> Counter:
    c: Counter = Counter()
    for b in cfg:
        c.update(b)
    return c


def key(cfg: List[Basis]) -> Key:
    return tuple(sorted(tuple(sorted(b)) for b in cfg))


def neighbors(cfg: List[Basis], fam: Set[Basis]) -> List[List[Basis]]:
    out = []
    for i in range(len(cfg)):
        for j in range(i + 1, len(cfg)):
            pool = Counter(cfg[i]) + Counter(cfg[j])
            for c1 in fam:
                if not Counter(c1) <= pool:
                    continue
                rem = pool - Counter(c1)
                c2 = frozenset(rem.keys())
                if Counter(c2) == rem and c2 in fam:
                    nc = list(cfg)
                    nc[i], nc[j] = c1, c2
                    out.append(nc)
    return out


def reach(start: List[Basis], fam: Set[Basis]) -> Set[Key]:
    seen = {key(start)}
    stack = [start]
    while stack:
        cur = stack.pop()
        for nxt in neighbors(cur, fam):
            if key(nxt) not in seen:
                seen.add(key(nxt))
                stack.append(nxt)
    return seen


def bucket(example: List[Basis], m: int, fam: Set[Basis]) -> Set[Key]:
    target = census(example)
    fl = list(fam)

    def rec(chosen, start):
        if len(chosen) == m:
            if census(chosen) == target:
                yield list(chosen)
            return
        for idx in range(start, len(fl)):
            chosen.append(fl[idx])
            yield from rec(chosen, idx)
            chosen.pop()

    return {key(c) for c in rec([], 0)}


if __name__ == "__main__":
    # Empirically confirm: reachability class == census bucket (White Part 3)
    for r, n, m in [(2, 4, 2), (2, 5, 2), (3, 5, 2), (2, 4, 3), (2, 6, 2)]:
        fam = {frozenset(s) for s in combinations(range(n), r)}
        ex = list(fam)[:m]
        while len(ex) < m:
            ex.append(list(fam)[0])
        cls, bkt = reach(ex, fam), bucket(ex, m, fam)
        print(f"U_{{{r},{n}}} m={m}: class={len(cls)} bucket={len(bkt)} "
              f"holds={cls == bkt}")

