function CENSUS(config):
    c <- empty multiset over ground elements
    for each basis B in config:
        for each element e in B:
            c[e] <- c[e] + 1
    return c

function NEIGHBORS(config, family):
    result <- []
    for i < j in indices(config):
        pool <- multiset(config[i]) + multiset(config[j])
        for c1 in family with multiset(c1) <= pool:
            rem <- pool - multiset(c1)
            c2 <- support(rem)
            if multiset(c2) == rem and c2 in family:
                result.append(config with i,j replaced by c1,c2)
    return result

function REACHABILITY_CLASS(start, family, NEIGHBORS):
    seen <- { key(start) }
    frontier <- [ start ]
    while frontier not empty:
        current <- frontier.pop()
        for nxt in NEIGHBORS(current, family):
            if key(nxt) not in seen:
                seen.add(key(nxt))
                frontier.push(nxt)
    return seen

